#include <iostream>
#include <vector>
#include <string>
using namespace std;

bool search(vector<int>& cells, vector<int>& rows, vector<int>& cols, vector<int>& boxes) {
    int best = -1, bestMask = 0, bestCount = 10;
    for (int i = 0; i < 81; i++) {
        if (cells[i] != 0) continue;
        int mask = ~(rows[i / 9] | cols[i % 9] | boxes[(i / 27) * 3 + (i % 9) / 3]) & 0x3FE;
        int count = __builtin_popcount(mask);
        if (count < bestCount) {
            best = i;
            bestMask = mask;
            bestCount = count;
            if (count <= 1) break;
        }
    }
    if (best == -1) return true;
    if (bestCount == 0) return false;
    int r = best / 9, c = best % 9, b = (best / 27) * 3 + (best % 9) / 3;
    for (int d = 1; d <= 9; d++) {
        int bit = 1 << d;
        if (!(bestMask & bit)) continue;
        cells[best] = d;
        rows[r] |= bit;
        cols[c] |= bit;
        boxes[b] |= bit;
        if (search(cells, rows, cols, boxes)) return true;
        cells[best] = 0;
        rows[r] &= ~bit;
        cols[c] &= ~bit;
        boxes[b] &= ~bit;
    }
    return false;
}

int main() {
    vector<string> board(9);
    for (int i = 0; i < 9; i++) {
        cin >> board[i];
    }

    vector<int> cells(81), rows(9, 0), cols(9, 0), boxes(9, 0);
    for (int i = 0; i < 9; i++) {
        for (int j = 0; j < 9; j++) {
            int d = board[i][j] - '0';
            cells[i * 9 + j] = d;
            if (d) {
                int bit = 1 << d;
                rows[i] |= bit;
                cols[j] |= bit;
                boxes[(i / 3) * 3 + j / 3] |= bit;
            }
        }
    }
    search(cells, rows, cols, boxes);
    for (int i = 0; i < 9; i++) {
        for (int j = 0; j < 9; j++) cout << cells[i * 9 + j];
        cout << "\n";
    }

    return 0;
}

